//This script relies on ISO 8601 format to support specific times in the JSON file but for more generalized dates where time specification isn't needed it supports YYYY/MM/DD for generalized Dates in your local timezone. 
//ISO 8061 timecodes can be created at this url https://www.timestamp-converter.com

const targetRoot = "performcarenj.org";
const hostname = window.location.hostname;

if (hostname === targetRoot || hostname.endsWith("." + targetRoot)) {
const cyberdowntimeDiv = document.getElementById('cyberdowntime');
async function runDateScript() {
 try {
 // Fetch and parse the JSON data
 const response = await fetch('/content/dam/amerihealth-caritas/performcare-nj/json/date.json'); // Use fetch in a browser environment
 if (!response.ok) {
 throw new Error(`HTTP error! Status: ${response.status}`);
 }
 const dateRanges = await response.json();

 // Get the current date for comparison
 const today = new Date();
 // Set time to start of day for comparison purposes to match YYYY-MM-DD strings
 // today.setHours(0, 0, 0, 0);

 // Find the active date range
 const activeRange = dateRanges.find(range => {
 const startDate = new Date(range.startDate);
 const endDate = new Date(range.endDate);
 // Check if today is within the start and end dates (inclusive)
 return today >= startDate && today <= endDate;
 });

 if (activeRange) {
 // Format the end date
 const endDateObj = new Date(activeRange.endDate);
 const formattedDate = formatEndDate(endDateObj);

 // Use regex to replace text in HTML
 const placeholderRegex = /%%END_DATE%%/g;
 const bodyHtml = document.body.innerHTML;
 document.body.innerHTML = bodyHtml.replace(placeholderRegex, formattedDate);

 } else {
 cyberdowntimeDiv.style.display = 'none';

 }

 } catch (error) {
 console.error("Error fetching or processing dates:", error);
 }
}

// Function to format the date as "Day, Month Day"
function formatEndDate(dateObj) {
 const daysOfWeek = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
 const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

 const dayOfWeek = daysOfWeek[dateObj.getDay()]; // getDay() returns 0-6
 const month = months[dateObj.getMonth()]; // getMonth() returns 0-11
 const dayOfMonth = dateObj.getDate();

 return `${dayOfWeek}, ${month} ${dayOfMonth}`;
}

// Run the script
runDateScript();
}

